#!/usr/bin/env python3
"""Build the self-contained ten-slide BreakHis capstone HTML presentation."""
from html import escape
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / 'docs/evidence/CAPSTONE_PRESENTATION.html'


def source(path, title):
    # HTTPS references also remain portable and private-path-free in PDF exports.
    return f'<a href="https://github.com/Sahith59/MagSet-Histo/blob/main/{escape(path)}">{escape(title)}</a>'


def slide(number, label, title, body, references, subtitle=''):
    refs = ' · '.join(source(*ref) for ref in references)
    return f'''<section class="slide" id="slide-{number}" aria-label="Slide {number}: {escape(title)}">
<header><span class="eyebrow">BREAKHIS / MASTER’S CAPSTONE</span><span class="section-label">{label}</span></header>
<h1>{title}</h1>{f'<p class="subtitle">{subtitle}</p>' if subtitle else ''}
<div class="content">{body}</div>
<footer><div>{refs}</div><span>{number:02d} / 10</span></footer></section>'''


def build():
    slides = []
    slides.append(slide(1, 'THE QUESTION', 'Reading tissue across magnifications', '''
<p class="lead">Can one research model recognize a breast-tumor subtype<br>from the microscope views available for a case?</p>
<div class="zooms"><span>40×</span><span>100×</span><span>200×</span><span>400×</span></div>
<div class="two"><div class="card"><h2>Main question</h2><p>Choose among <strong>eight tumor subtypes</strong>, even when some magnifications are withheld.</p></div>
<div class="card accent"><h2>Secondary question</h2><p>Combine the saved subtype scores into <strong>benign / malignant</strong> groups.</p></div></div>
<p class="takeaway">A reproducible research prototype. Clinical use has not been established.</p>''', [('README.md', 'Project overview'), ('docs/CAPSTONE_DELIVERY_PLAN.md', 'Capstone scope')]))
    slides.append(slide(2, 'THE DATA', 'Many images. Few independent cases.', '''
<div class="stats"><div><strong>7,909</strong><span>tissue images</span></div><div><strong>4</strong><span>magnifications</span></div><div><strong>8</strong><span>subtypes</span></div></div>
<div class="two"><div class="card"><h2>What we group together</h2><p>All related fields and magnifications stay within their provider-case role.</p><p>We do not assume that equally numbered fields align across zooms.</p></div>
<div class="card"><h2>What remains uncertain</h2><p><strong>82</strong> subtype-qualified provider keys;<br><strong>81</strong> bare identifiers; <strong>70</strong> numeric stems.</p><p>Exact clinical-patient relationships remain unverified.</p></div></div>
<p class="takeaway">More photographs of one case do not create more independent cases.</p>''', [('docs/reviews/CAPSTONE_PROTOCOL_REVIEW.md', 'Protocol review'), ('docs/CAPSTONE_BEFORE_AND_NOW.md', 'Data and identity audit')]))
    slides.append(slide(3, 'HISTORICAL CONTEXT', 'Two different experiments', '''
<div class="two"><div class="card"><span class="tag">SUPPLIED NOTEBOOKS · SAVED RESULTS</span><div class="big-number">93.73% / 94.99%</div><h2>Single-image accuracy</h2><ul><li>One 40× image; eight classes</li><li>Random 80/20 image split</li><li>Validation reused for model selection</li><li>EfficientNet attention variants</li></ul></div>
<div class="card accent"><span class="tag">CURRENT GROUPED VALIDATION</span><div class="big-number">45.7% / 38.3%</div><h2>Provider-case accuracy</h2><ul><li>Aggregate fields within each case</li><li>All four zooms; 15 availability subsets</li><li>Case roles enforced by the protocol</li><li>Frozen Phikon representation</li></ul></div></div>
<p class="takeaway">This is not a measured drop on the same test. The unit, split and model differ.</p>''', [('docs/reviews/CAPSTONE_ORIGINAL_RESULTS_REVIEW.md', 'Original saved-output audit'), ('docs/CAPSTONE_BRIDGE_RESULTS.md', 'Prediction-unit bridge')]))
    slides.append(slide(4, 'THE RETAINED MODEL', 'From tissue fields to eight scores', '''
<div class="pipeline"><div class="node"><b>1 · Read each image</b><p>Official processor:<br>shortest-edge resize,<br>224 × 224 center crop</p><span>Frozen Phikon-v2 → 1,024 features</span></div><i>→</i><div class="node"><b>2 · Combine available views</b><p>Mean fields within each zoom<br>→ fitting-only normalization<br>→ mean available zooms</p><span>Append four availability flags</span></div><i>→</i><div class="node"><b>3 · Classify the case</b><p>Saved logistic classifier<br>→ eight subtype probabilities</p><span>Optional fixed benign / malignant sum</span></div></div>
<div class="two compact"><div class="card"><h2>Missing views are explicit</h2><p>One to four magnifications can be supplied. Every nonempty combination is evaluated.</p></div><div class="card"><h2>A conventional baseline</h2><p>Mean pooling is an established control. This is not a new multiview transformer.</p></div></div>
<p class="note">The center crop does not encode every original pixel. Fields are pooled without invented spatial pairing.</p>''', [('docs/reviews/CAPSTONE_MODEL_REVIEW.md', 'Model and processor review'), ('docs/BREAKHIS_FIRST_RESULTS.md', 'Retained reference')]))
    slides.append(slide(5, 'THE EVALUATION', 'Keep the exam separate from fitting', '''
<div class="roles"><div><strong>46</strong><span>fitting cases</span></div><div class="selected"><strong>8</strong><span>validation cases</span></div><div class="excluded"><strong>28</strong><span>excluded outer-role cases</span></div></div>
<div class="two"><div class="card"><h2>Five overlapping provider holdouts</h2><p>Two inner arrangements: <strong>812 / 813</strong>.<br>One validation case per subtype in each run.<br>All <strong>15</strong> nonempty view subsets.</p></div><div class="card"><h2>The main score is macro F1</h2><p>Eight classes contribute equally.<br>Average over subsets, then over five trials.<br>Accuracy and subtype recall stay visible.</p></div></div>
<p class="takeaway"><strong>22 / 20</strong> distinct validation cases; <strong>31</strong> in their union. No globally pristine confirmation cohort remains.</p>''', [('docs/reviews/CAPSTONE_PROTOCOL_REVIEW.md', 'Roles and overlap'), ('docs/BREAKHIS_FIRST_RESULTS.md', 'Evaluation endpoint')]))
    slides.append(slide(6, 'THE PRIMARY RESULT', 'Exact subtype recognition remains weak', '''
<div class="result-grid"><div class="metric-card"><span>ARRANGEMENT 812</span><strong>0.3843</strong><b>macro F1</b><p>45.7% case accuracy</p></div><div class="metric-card"><span>ARRANGEMENT 813</span><strong>0.3169</strong><b>macro F1</b><p>38.3% case accuracy</p></div><div class="verdict"><h2>Keep the frozen reference</h2><p>Last-block adaptation and supervised ResNet failed their registered improvement gates.</p></div></div>
<div class="regional"><div><span class="tag">SEPARATE MATCHED REGIONAL-VIEW EXPERIMENT</span><p>Macro F1 change: <strong>−0.0058 / +0.0059</strong>.<br>Mixed tiny effects; improvement gate failed.</p></div><div><p>Compared against its own fixed-<i>C</i> control.<br>The historical reference used a <i>C</i> grid;<br>its tuning budget is different.</p></div></div>
<p class="takeaway">Successful execution and reproducibility do not establish strong predictive performance.</p>''', [('docs/BREAKHIS_SUPERVISED_RESULTS.md', 'Eight-class comparison'), ('docs/BREAKHIS_MULTICROP_RESULTS.md', 'Regional-view result')]))
    slides.append(slide(7, 'SECONDARY · RETROSPECTIVE', 'The broad group is easier than the subtype', '''
<p class="slide-intro">Fixed malignant score = sum of four malignant-subtype probabilities. Predict malignant at ≥ 0.5.</p>
<table class="binary"><thead><tr><th>Saved pipeline</th><th>Accuracy</th><th>Sensitivity</th><th>Specificity</th><th>AUROC</th></tr></thead><tbody>
<tr class="highlight"><th>Frozen reference</th><td>87.0 / 80.7%</td><td>98.7 / 91.3%</td><td>75.3 / 70.0%</td><td>.9617 / .9408</td></tr>
<tr><th>Adapted</th><td>86.5 / 82.0%</td><td>98.7 / 93.3%</td><td>74.3 / 70.7%</td><td>.9658 / .9558</td></tr>
<tr><th>Supervised</th><td>84.7 / 82.2%</td><td>94.3 / 87.7%</td><td>75.0 / 76.7%</td><td>.8875 / .9217</td></tr></tbody></table>
<p class="note">Each pair is 812 / 813; five-trial means over all 15 subsets. AUROC is ranking, not accuracy.</p>
<div class="callout"><strong>Same saved eight-class models. A different label question.</strong><p>No binary fitting, calibration or threshold search. Reused validation; no binary winner selected. The eight-class gate is unchanged.</p></div>
<p class="note">Always-malignant analytic reference: 50% accuracy (four benign / four malignant per run). The paper’s 86.22% binary image result uses another protocol.</p>''', [('docs/CAPSTONE_BINARY_RESULTS.md', 'All binary results and limitations'), ('docs/reviews/CAPSTONE_BINARY_REVIEW.md', 'Independent binary audit')]))
    slides.append(slide(8, 'WHAT THE DIAGNOSTICS SHOW', 'A large fitting–validation gap', '''
<div class="two"><div class="card gap"><h2>Supervised ResNet</h2><div class="bar-label"><span>Fitting balanced accuracy</span><b>99.6–99.7%</b></div><div class="bar"><span style="width:99.65%"></span></div><div class="bar-label"><span>Validation balanced accuracy</span><b>37–40%</b></div><div class="bar muted"><span style="width:38.5%"></span></div><p>Case endpoints across arrangements 812 / 813.</p></div>
<div class="card"><h2>Very limited rare-class support</h2><p>Each fitting set has just <strong>one adenosis</strong> case and <strong>one phyllodes</strong> case.</p><p>The direct image classifier is weak on validation too. Changing averaging alone did not rescue the result.</p></div></div>
<p class="takeaway">The gap is measured. No single cause has been established.</p>
<p class="note">Repeated fields improve image coverage; they cannot supply new independent cases for a rare subtype.</p>''', [('docs/BREAKHIS_SUPERVISED_RESULTS.md', 'Fitting and validation endpoints'), ('docs/CAPSTONE_BRIDGE_RESULTS.md', 'Image and case diagnostic'), ('docs/BREAKHIS_DIAGNOSIS_RESULTS.md', 'Rare-class support')]))
    slides.append(slide(9, 'THE DEMONSTRATION', 'Replay one case across available views', '''
<div class="stats demo-stats"><div><strong>121</strong><span>raw fields</span></div><div><strong>15</strong><span>view combinations</span></div><div><strong>~39 s</strong><span>scheduled replay run</span></div></div>
<div class="two"><div class="card"><h2>A prespecified example</h2><p>The lexicographically first validation case was chosen before inspecting its outcome.</p><p>Fresh inference reproduced all archived outputs with maximum difference <strong>6.05 × 10⁻⁸</strong>.</p></div><div class="card accent"><h2>What the viewer shows</h2><p>Toggle available magnifications; inspect eight subtype scores and the fixed benign / malignant sum.</p><p><a class="demo-link" href="https://github.com/Sahith59/MagSet-Histo/blob/main/docs/evidence/CAPSTONE_PREDICTION_REPLAY.html">View / download replay HTML ↗</a></p></div></div>
<p class="takeaway">The viewer replays recorded outputs. It does not accept live image uploads.</p>''', [('docs/evidence/CAPSTONE_PREDICTION_REPLAY.html', 'Recorded prediction viewer'), ('docs/CAPSTONE_DELIVERY_PLAN.md', 'Demonstration and delivery')]))
    slides.append(slide(10, 'DELIVERY AND NEXT STEPS', 'Complete the capstone with checked evidence', '''
<div class="two"><div class="card"><h2>Ready to present</h2><ul><li>Audited data, grouping and source results</li><li>Reproducible model and inference chain</li><li>Fixed-role baselines and negative comparisons</li><li>Independent numerical checks and demo</li></ul></div><div class="card"><h2>Still open</h2><ul><li>Stronger transfer to exact subtypes</li><li>Clinical identity reconciliation</li><li>Genuinely fresh confirmation data</li><li>A tested novel mechanism, later</li></ul></div></div>
<div class="timeline"><div><b>November 17–18</b><span>Reviewable capstone package<br>and revisions</span></div><i>→</i><div><b>Around November 20</b><span>Presentation · tentative<br>Exact date and rubric not supplied</span></div><i>→</i><div><b>After the capstone</b><span>Novel-method and paper work<br>with explicit evidence requirements</span></div></div>
<p class="takeaway">A reproducible engineering study with useful negative findings. Clinical validation remains future work.</p>''', [('docs/CAPSTONE_DELIVERY_PLAN.md', 'Delivery plan'), ('paper/capstone-presentation-outline.md', 'Presentation source outline')]))
    assert len(slides) == 10
    css = '''
:root{--navy:#102d43;--teal:#087f8c;--ink:#18374a;--muted:#536b79;--line:#d9e5e8;--pale:#edf6f6}
*{box-sizing:border-box}body{margin:0;background:#071b29;color:var(--ink);font-family:Arial,Helvetica,sans-serif}#stage{width:1280px;height:720px;position:relative;transform-origin:top left}#shell{position:absolute;left:50%;top:50%;width:1280px;height:720px;transform:translate(-50%,-50%)}
.slide{display:none;width:1280px;height:720px;padding:32px 54px 48px;background:#fff;position:relative;overflow:hidden;border-top:9px solid var(--teal)}.slide.active{display:block}header{display:flex;justify-content:space-between;align-items:center;height:26px}.eyebrow{font-size:14px;letter-spacing:2px;font-weight:700;color:var(--teal)}.section-label{font-size:14px;letter-spacing:1.4px;font-weight:700;color:var(--muted)}h1{font-size:48px;line-height:1.08;letter-spacing:-1.6px;color:var(--navy);margin:23px 0 24px;max-width:1160px}h2{font-size:25px;line-height:1.18;color:var(--navy);margin:0 0 13px}p{font-size:23px;line-height:1.38;margin:0 0 15px}strong{font-weight:750}.lead{font-size:29px;line-height:1.35;margin-bottom:22px}.two{display:grid;grid-template-columns:1fr 1fr;gap:23px}.card{padding:25px 27px;background:#f3f6f7;border:1px solid var(--line);border-radius:10px}.card p:last-child{margin-bottom:0}.accent{background:var(--pale);border-color:#b7d8d9}.takeaway{font-size:24px;font-weight:700;color:var(--teal);margin-top:23px;line-height:1.3}.note{font-size:18px;color:var(--muted);line-height:1.35;margin-top:15px}.tag{font-size:14px;font-weight:700;letter-spacing:.7px;color:var(--teal)}.big-number{font-size:42px;font-weight:750;letter-spacing:-1px;color:var(--navy);margin:15px 0 10px}ul{padding-left:23px;margin:11px 0 0}li{font-size:23px;line-height:1.38;margin:9px 0}footer{position:absolute;bottom:18px;left:54px;right:54px;display:flex;justify-content:space-between;gap:16px;font-size:14px;color:var(--muted);border-top:1px solid var(--line);padding-top:10px}footer a{color:var(--muted);text-decoration:none;border-bottom:1px solid #afc3ca}footer>span{white-space:nowrap;font-weight:700;letter-spacing:1px}a{color:var(--teal)}.zooms{display:flex;gap:12px;margin:0 0 23px}.zooms span{padding:10px 27px;border:1px solid #b7d8d9;color:var(--teal);border-radius:25px;background:var(--pale);font-size:24px;font-weight:700}.stats{display:flex;gap:65px;margin:4px 0 26px}.stats>div{display:flex;flex-direction:column}.stats strong{font-size:68px;line-height:1;letter-spacing:-2px;color:var(--teal)}.stats span{font-size:21px;margin-top:9px;color:var(--muted)}.pipeline{display:flex;align-items:stretch;gap:13px;margin:8px 0 25px}.node{width:calc((100% - 82px)/3);background:var(--pale);border-radius:10px;padding:23px 20px}.node b{display:block;font-size:23px;color:var(--navy);margin-bottom:15px}.node p{font-size:21px;line-height:1.5}.node span{font-size:18px;line-height:1.35;display:block;color:var(--teal);font-weight:700}.pipeline i{align-self:center;font-size:31px;font-style:normal;color:var(--teal)}.compact .card{padding:20px 23px}.compact h2{font-size:23px}.compact p{font-size:21px}.roles{display:flex;gap:16px;margin-bottom:23px}.roles>div{flex:1;background:#f2f5f6;padding:18px 24px;border-radius:8px;display:flex;gap:20px;align-items:center}.roles strong{font-size:57px;line-height:1;color:var(--navy)}.roles span{font-size:21px;line-height:1.25}.roles .selected{background:var(--teal);color:#fff}.roles .selected strong{color:#fff}.roles .excluded{border:1px dashed #91a9b5;background:#fff}.result-grid{display:grid;grid-template-columns:1fr 1fr 1.1fr;gap:20px}.metric-card{padding:24px;background:var(--pale);border-radius:10px}.metric-card>span{font-size:14px;letter-spacing:1px;font-weight:700;color:var(--muted)}.metric-card strong{display:block;font-size:66px;line-height:1.1;color:var(--teal);letter-spacing:-2px;margin:12px 0 4px}.metric-card b{font-size:24px}.metric-card p{font-size:22px;margin:12px 0 0}.verdict{padding:22px 12px}.verdict p{font-size:23px}.regional{display:grid;grid-template-columns:1.05fr 1fr;gap:25px;margin-top:22px;padding:21px 25px;border:1px solid var(--line);border-radius:9px}.regional p{font-size:21px;margin:10px 0 0}.slide-intro{font-size:22px;margin-bottom:22px}.binary{border-collapse:collapse;width:100%;font-size:21px;margin-bottom:12px}.binary th,.binary td{text-align:left;padding:17px 12px;border-bottom:1px solid var(--line);white-space:nowrap}.binary thead th{font-size:17px;color:var(--muted);padding-top:8px}.binary .highlight{background:var(--pale)}.binary th:first-child{width:23%}.callout{border-left:5px solid var(--teal);padding:15px 20px;background:var(--pale);margin-top:18px}.callout strong{font-size:23px}.callout p{font-size:21px;margin:8px 0 0}.bar-label{display:flex;justify-content:space-between;font-size:19px;margin:22px 0 8px}.bar{height:28px;background:#dce8ea;border-radius:5px;overflow:hidden}.bar span{display:block;height:100%;background:var(--teal)}.bar.muted span{background:#9c6470}.gap p{font-size:18px;color:var(--muted);margin-top:20px}.demo-stats{gap:95px}.demo-stats strong{font-size:63px}.demo-link{font-weight:700;font-size:22px;text-decoration:none;border-bottom:2px solid var(--teal)}.timeline{margin-top:23px;display:flex;align-items:center;gap:22px}.timeline>div{flex:1}.timeline b{font-size:23px;color:var(--teal);display:block;margin-bottom:9px}.timeline span{font-size:19px;line-height:1.35}.timeline i{font-size:26px;color:var(--teal);font-style:normal}nav{position:fixed;right:20px;bottom:14px;display:flex;gap:9px;align-items:center;z-index:10;color:white;font-size:14px}nav button{background:#163c50;border:1px solid #497182;color:white;font-size:20px;border-radius:6px;padding:6px 15px;cursor:pointer}nav button:focus-visible{outline:3px solid #7be1dc}nav button:disabled{opacity:.35;cursor:default}
#slide-7 .binary th,#slide-7 .binary td{padding-top:13px;padding-bottom:13px}#slide-7 .callout{margin-top:13px;padding-top:12px;padding-bottom:12px}#slide-7 .note{font-size:17px;line-height:1.3;margin-top:12px}
@media print{@page{size:1280px 720px;margin:0}html,body{width:1280px;margin:0;background:#fff;print-color-adjust:exact;-webkit-print-color-adjust:exact}#shell{position:static;width:1280px;height:auto;transform:none!important}#stage{position:static;width:1280px;height:auto;transform:none!important}.slide,.slide.active{display:block;break-after:page;page-break-after:always;break-inside:avoid;margin:0;width:1280px;height:720px}.slide:last-child{break-after:auto;page-break-after:auto}nav{display:none}}
'''
    js = '''
const slides=[...document.querySelectorAll('.slide')];let current=0;
function show(n){current=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,i)=>{s.classList.toggle('active',i===current);s.setAttribute('aria-hidden',String(i!==current));});document.getElementById('count').textContent=`${current+1} / ${slides.length}`;document.getElementById('previous').disabled=current===0;document.getElementById('next').disabled=current===slides.length-1;location.hash=`slide-${current+1}`;}
function resize(){const scale=Math.min(innerWidth/1280,(innerHeight-55)/720);document.getElementById('stage').style.transform=`scale(${scale})`;const shell=document.getElementById('shell');shell.style.width=`${1280*scale}px`;shell.style.height=`${720*scale}px`;}
document.getElementById('previous').onclick=()=>show(current-1);document.getElementById('next').onclick=()=>show(current+1);
addEventListener('keydown',e=>{if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(current+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(current-1)}if(e.key==='Home')show(0);if(e.key==='End')show(slides.length-1)});
addEventListener('resize',resize);const initial=Number(location.hash.replace('#slide-',''));show(Number.isFinite(initial)&&initial>0?initial-1:0);resize();
'''
    html = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BreakHis — Master’s Capstone</title><style>' + css + '</style></head><body><main id="shell"><div id="stage">' + ''.join(slides) + '</div></main><nav aria-label="Slide controls"><button id="previous" aria-label="Previous slide">←</button><span id="count"></span><button id="next" aria-label="Next slide">→</button></nav><script>' + js + '</script></body></html>'
    assert html.count('<section class="slide"') == 10
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT.write_text(html)
    print(f'Built {OUTPUT.relative_to(ROOT)}: 10 slides, 1280 × 720, self-contained assets')


if __name__ == '__main__':
    build()
